    // BEGIN GUIDE TRANSLATIONS
    guide_text_260313e4ac64571f: "{name_a}은 뉴욕시 기관이 이미 공개한 계약, 토지 이용 신청, 규칙, 회의, 공무원 시험과 관련 기관·단체의 기록을 모으고, 각 기록에 해당 공식 출처 링크를 유지합니다.",
    guide_text_641498d11bf44328: "처음 방문했다면 첫 번째 튜토리얼부터 시작하세요. 실제 검색 한 번으로 약 10분 동안 진행하며 계정이나 이메일 주소가 필요하지 않습니다. 다음 두 튜토리얼은 공개 공고에서 그 근거 법률을 추적하고, 기관에서 대금을 받는 단체를 거쳐 낙찰 기록 하나로 이어집니다.",
    guide_text_65173c70d8e1e737: "이미 할 일이 있다면 바로 사용 방법으로 가세요. 기록의 의미가 궁금하거나 처음 보는 단어가 있다면 이해와 참고에서 답을 찾을 수 있으며, 먼저 수업을 마칠 필요는 없습니다.",
    guide_text_f28a7d73644b0422: "튜토리얼. 실제 사례 하나를 따라가며 버튼 하나의 기능을 넘어 전체 과정을 이해합니다.",
    guide_text_b4074d9152312c1c: "이미 정한 작업에 대한 짧은 안내로, 실제 화면의 명칭을 사용합니다.",
    guide_text_78273bdd4958a269: "기록이 알려 주는 것과 알려 주지 않는 것, 데이터의 한계를 설명합니다.",
    guide_text_ea655ad159977ecf: "작업 중 찾아볼 정의, 조작 기능, 범위입니다.",
    guide_text_fc81d74c51395819: "각 글에는 편집자가 실제 사이트와 마지막으로 대조한 날짜가 있습니다. 확인 뒤 직접 입력하는 날짜이며, 사이트를 다시 빌드해도 바뀌지 않습니다.",
    guide_text_d2871a9838a24e99: "안내서를 읽을 언어를 선택하세요. 번역에는 {name_a}의 다른 화면과 같은 기능 명칭을 사용합니다. 공식 명칭, 식별자, 인용한 출처 원문은 원래 언어를 유지합니다.",
    guide_text_0b1c918dea55487f: "잘못되거나 빠진 내용이 있나요? [소개 페이지의 의견 양식]({link_a})으로 관리 담당자에게 알릴 수 있으며 계정은 필요 없습니다.",
    guide_text_b50e208649012afa: "1단계 — 연결의 세부 정보 열기",
    guide_text_63d7a67f83b8d352: "{name_f}를 켜고 [Parks and Recreation]({link_a})을 여세요. 계정은 필요 없습니다. **{control_b}**에서 기록 제목 옆의 **{control_c}**를 선택하세요. 화면 낭독기는 **{control_d}**라고 읽습니다. 해당 기록의 **{control_e}** 패널이 열립니다.",
    guide_text_0cc284d7559fd468: "예제에서는 **Update to Parks List of Qualifying Documents for Disability Membership Fee**가 있다면 옆의 **{control_b}**를 누르세요. 기록이 제공될 때 [예제 연결 링크]({link_a})는 해당 패널을 바로 엽니다.",
    guide_text_016cbce48bd3bea2: "제목 옆에 {control_a} 링크가 있는 공원 규칙 기록.",
    guide_text_58f258874f85f287: "영어 화면.",
    guide_text_0ebe2d3e3c918e36: "1. {control_a}에서 이 기록 제목 옆의 {control_b}를 선택하세요.",
    guide_text_caea93f207e642e6: "휴대전화 이미지 확대",
    guide_text_1e9e2f27e2473c5d: "데스크톱 이미지 확대",
    guide_text_727296e89e7b7050: "2단계 — 근거와 출처 읽기",
    guide_text_b096b7929e479242: "**{control_a}**에서 일치 근거 표시와 날짜를 읽으세요. 예제의 **{control_b}**와 **Matched to the agency's published name**은 근거를 설명합니다. **{control_c}**에서 관계인 **issued rule**을 읽으세요. 패널의 **{control_d}**를 열어 공식 출처와 비교한 뒤 돌아오세요.",
    guide_text_ae1bbd19f3ff6c02: "이는 표시된 연결을 뒷받침할 뿐 준수 여부나 부정행위에 대한 판단이 아닙니다. [기록이 연결되는 방식]({link_a})에서 다른 일치 표시를 설명합니다.",
    guide_text_d05504aea51fa236: "일치 근거, 출처, 링크 복사 기능을 표시하는 펼쳐진 {control_a}.",
    guide_text_be58a1edd1426736: "1. 선택한 기록의 {control_b}를 읽으세요. 2. {control_a}으로 이 패널을 다시 열 수 있습니다.",
    guide_text_d20609214f01766f: "3단계 — 링크로 증거 다시 열기",
    guide_text_a3ccbb7c032c92e8: "패널 아래의 **{control_a}**을 선택하세요. 주소를 새 탭에 붙여 넣고 동일 기록의 **{control_b}**가 펼쳐지는지 확인하세요. 이 주소를 뒷받침하는 주장과 함께 보관하세요.",
    guide_text_07b6d5bba6d2a50f: "출처나 패널이 없을 때",
    guide_text_8a552edcc3e77c2e: "일부 계약 연결에는 별도 공고 출처가 없습니다. 패널에서 링크된 기록 제목을 열고 그 기록 자체의 출처 링크를 사용하세요. 출처 증거가 없다고 관계가 없다는 뜻은 아닙니다. 복사한 주소가 패널을 열지 않으면 **{control_a}**로 돌아가 **{control_b}**로 현재 페이지의 연결을 선택하세요. {name_c}가 없으면 기록을 직접 읽을 수 있지만 패널은 사용할 수 없습니다.",
    guide_text_9881cfd03e31b031: "1단계 — 기록 두 개 고정하기",
    guide_text_bad689102113bd55: "{name_e}를 켜고 [West 50th Street 낙찰 공고]({link_a})를 여세요. 기록의 작업 중 **{control_c}**를 선택하세요. 확인 표시는 작업 공간 링크와 항목 수를 보여 줍니다. [해당 단체]({link_b})를 열어 거기서도 **{control_d}**를 선택하세요. Pin은 검색 결과가 아닌 개별 기록에 표시됩니다.",
    guide_text_3f7b69ad1c2414b3: "고정 기능이 포함된 낙찰 공고 작업 줄.",
    guide_text_8bbd4ee14deea59b: "1. 고정은 개별 기록의 인쇄·내보내기 기능 옆에 있습니다.",
    guide_text_8585b7df9dca9134: "같은 기록 작업 줄에 표시된 고정 완료 확인 링크.",
    guide_text_9ab9eaee258283f2: "1. 고정 확인 표시는 항목 수를 보여 주며 내 조사를 엽니다.",
    guide_text_910aec83d41a6d43: "2단계 — 메모 추가하고 확인하기",
    guide_text_6b55428f4d80086b: "페이지 바닥글의 **{control_b}** 또는 [My investigation]({link_a})를 여세요. 두 기록이 모두 **{control_c}** 아래에 있는지 확인하세요. 계정은 필요 없습니다. 기록 아래 **{control_d}**에 입력하고 입력란 밖을 눌러 저장하세요. 새로고침한 뒤 메모가 남아 있는지 확인하세요.",
    guide_text_696cdea60840aeec: "일반적인 로그아웃 방문에서는 모음이 이 브라우저에 남으며, 사이트 데이터를 지우면 사라집니다. {name_a} 이메일로 인식된 세션은 여러 기기에서 고정을 유지할 수 있습니다.",
    guide_text_77f102629d7c3dfa: "3단계 — 사본 내보내기",
    guide_text_5e1a2f81fdf591ec: "항목 아래에서 스프레드시트는 **{control_a}**, 구조화된 데이터는 **{control_b}**를 선택하세요. 내려받은 파일을 열어 기록, 메모, 링크를 확인하세요. 두 파일 모두 고정된 사본이며 업데이트되지 않습니다. **{control_c}**는 브라우저 인쇄 창을 열어 인쇄하거나 {name_d}로 저장합니다.",
    guide_text_39fa6ae3bd33ee06: "고정된 낙찰 기록과 임시 예제 메모 위에 파일 내보내기 기능이 있는 조사 작업 공간.",
    guide_text_9dfc02b4b49a0073: "1. {control_b} 또는 {control_a}는 고정 사본을 저장합니다. 2. 고정 기록 아래 메모를 추가하고 바깥을 눌러 저장하세요.",
    guide_text_beca93a71cd9edcf: "4단계 — 메모를 확인한 뒤에만 공유하기",
    guide_text_7ff034137fca53c3: "항목 아래 **{control_a}**를 선택하기 전에 메모를 읽으세요. 이 작업은 메모를 포함한 스냅샷을 {name_b}에 올립니다. 링크가 있는 누구나 **90일** 동안 비밀번호 없이 읽을 수 있습니다. 로컬 목록과 별개이며 이후 수정은 반영되지 않습니다.",
    guide_text_f9d649ab2be6550d: "반환된 링크를 새 탭에서 여세요. **Shared investigation**에는 편집 기능 없이 기록과 메모가 표시되어야 합니다. 받은 사람은 자신의 조사로 사본을 가져올 수 있습니다.",
