    guide_text_358a3c3e3e8eb66f: "남는 결과",
    guide_text_da0cd9290737dcc1: "목록의 필터는 기록 유형이 가진 속성에 따라 다릅니다. 금액은 계약, 단계는 회의의 속성입니다. 각 목록이 제공하는 필터는 해당 목록 자체를 기준으로 보세요.",
