    guide_text_e448155e07523657: "기구와 지역",
    guide_text_e3929fded66f3ac1: "정보를 공개하고 업무를 수행하는 시 부서나 사무소",
    guide_text_623a5bbd0ce0ee19: "기관 이름은 바뀔 수 있으나 이곳에서는 같은 페이지를 유지",
    guide_text_3103aec7649a7f3c: "자치구 내에서 번호를 매기는 임명된 지역 위원회",
    guide_text_c47d5976501ed936: "여러 자치구에 7번 위원회가 있으므로 번호만으로 식별할 수 없음",
