    guide_text_b953ebbdb58ac0dc: "공식 날짜",
    guide_text_333a844c817c2e28: "청문회, 마감일, 발효일처럼 기록이 다루는 날짜",
    guide_text_4b54bcdf1ba4c9d6: "공개 날짜가 아님",
    guide_text_29473cdce82e27cd: "공개 날짜",
    guide_text_067323e3a7f17483: "사건 날짜가 아님",
    guide_text_ad730eed631628ca: "선택한 날 이전 또는 당일의 기록만 남기는 필터",
    guide_text_fc8154190a548aa5: "사이트가 당시 알던 내용의 스냅샷이 아님",
