    guide_text_95c89904993382cb: "{name_a} 사용하기 · 안내서",
    guide_text_3c95dbee5ab32e7d: "{name_a}에서 뉴욕시 공공 기록을 읽고, 하러 온 작업을 수행하고, 기록의 뜻을 이해하고, 세부 내용을 찾는 방법을 배우세요.",
