    guide_text_008cc62f8632f152: "{name_a} 사용하기",
    guide_text_3d2ed81259c40e96: "배우기, 하기, 이해하기, 찾아보기에 따른 네 가지 입구.",
    guide_text_a08cf344721d119e: "시작할 곳",
    guide_text_a3d77913305af74c: "이 안내서 소개",
    guide_text_38c86e7d74743b49: "{name_a}은 비공식 읽기 보조 도구입니다. 각 기록을 공식 출처에서 확인하세요.",
    guide_text_9b8197f3d9d1b528: "데이터 소개",
    guide_text_611d488100fd45e5: "공공 기록이 알려 주는 것 · {name_a}",
    guide_text_1acba7083479a93a: "{name_a}의 기록은 시가 무언가 공개했다는 증거입니다. 결정까지 보여 주는지는 읽는 기록의 종류에 달려 있습니다.",
    guide_text_4c6226ecc7a75837: "안내서로 돌아가기",
    guide_text_cf6c27f433c20dcf: "공개 기록이 정부 행동에 대해 확립하는 것과 의도적으로 결론 내리지 않는 것.",
    guide_text_a3aae40a974e7f32: "관련 페이지",
    guide_text_5d043323925f135e: "{name_a}의 공개 청문회와 회의",
    guide_text_ab13102844ac1899: "안내서에 쓰인 용어집",
