    guide_text_0662971ca4535ff5: "토지 이용 신청 공개 심사, Department of City Planning",
    guide_text_8c6bd74ccca6bb39: "유형별 공공 기록 탐색",
    guide_text_2c7e91949fe059ce: "기록이 연결되는 방식 · {name_a}",
    guide_text_95b1c09f5051bb30: "{name_a}의 두 기록 연결은 근거가 명시된 주장입니다. 주장 내용, 확인 방법, 한계를 설명합니다.",
    guide_text_ba1a082691ee350d: "{name_a}이 두 기록을 연결할 때의 의미, 주장 확인 방법, 분명한 관계도 연결되지 않는 이유.",
    guide_text_d7004a7d79a46dca: "날짜와 빈칸의 뜻 · {name_a}",
    guide_text_77ebe53aa882229d: "기록에는 여러 날짜와 빈칸이 있습니다. 구분하는 것이 안전하게 읽는 핵심입니다.",
    guide_text_7d17bd488fb541fc: "기록의 날짜를 구분하고 빈 필드에 없는 의미를 보태지 않고 읽는 방법.",
