    guide_text_0a50d115acdd7d58: "표시와 과거 양상 · {name_a}",
    guide_text_6114a9b5eb0bbe11: "{name_a}의 표시와 과거 양상 설명은 통계적 맥락이며 판정이 아닙니다. 각각 무엇을 세고 정확한 규칙은 어디 있는지 설명합니다.",
    guide_text_924377705beee643: "계산된 설명이 무엇이고 무엇이 아닌지, 각 정확한 규칙의 문서 위치.",
