    public_input_explainer_open: "공공 의견 수렴은 어떻게 작동하는가",
    public_input_explainer_what_html: "<p>공개 절차에 참여한다는 것은 공식 기록에 무언가를 남기는 일입니다. 공청회에서 발언하거나, 공표된 마감일 전에 서면 의견을 제출하는 것입니다. 그 기록이 이후 어떤 역할을 하는지는 절차마다 다르며, 이 사이트의 모든 목록은 어느 경우에 해당하는지 밝힙니다.</p>",
    public_input_explainer_destinations_heading: "당신이 말한 내용이 도달하는 곳",
    public_input_explainer_destinations_html: "<ul><li><b>공개 의견 기록</b> — 의견 수렴 기간에 제출된 서면 의견은 기관이 반드시 검토해야 하는 기록에 들어갑니다.</li><li><b>공청회 증언</b> — 공청회에서 말한 내용은 그 공청회의 증언 기록에 들어갑니다.</li><li><b>속기록</b> — 일부 절차는 회의 내용을 그대로 옮긴 기록을 공개합니다.</li><li><b>회의록</b> — 다른 기관은 대신 무슨 일이 있었는지 요약해 공개합니다.</li><li><b>결정 문서</b> — 기관이 결정을 기록할 때 공개되는 별도의 기록입니다.</li></ul><p>일부 절차는 접수된 의견에 답하는 보고서도 공개합니다. 이는 위 도달처 가운데 하나이며, 각 목록이 해당 여부를 밝힙니다.</p>",
    public_input_explainer_limits_heading: "참여의 한계",
    public_input_explainer_limits_html: "<p>공무원의 답변은 기록 등재와는 별개입니다. 의견을 제출하거나 증언하면 당신의 말이 기록에 남지만, 어떤 공무원도 개인적으로 답변할 의무는 없습니다. 이 사이트는 그런 답변을 약속하지 않습니다.</p><p>의견의 수는 의견의 수일 뿐입니다. 기관은 자신이 따르는 법에 비추어 발언 내용을 판단하므로, 이 사이트는 어떤 의견 총계도 찬성이나 반대로 제시하지 않으며 의견의 양을 표결로 취급하지 않습니다.</p>",
    public_input_explainer_examples_heading: "실제로 작동하는 세 가지 방식",
    public_input_explainer_example_hearing: "법안에 관한 시의회 공청회에서 발언하거나 서면 증언을 제출하십시오.",
    public_input_explainer_example_hearing_surface: "예정된 공청회와 회의 보기",
    public_input_explainer_example_rule: "공표된 마감일 전에 기관의 규칙 제정안에 의견을 내십시오.",
    public_input_explainer_example_rule_surface: "진행 중인 규칙 의견 수렴 기간 보기",
    public_input_explainer_example_contract: "의견 수렴 기간에 낙찰 예정 건에 의견을 내십시오.",
    public_input_explainer_example_contract_surface: "계약 의견 마감일 보기",
    public_input_explainer_official_source: "공식 출처: {source}",
    public_input_explainer_method_summary: "이 설명의 출처",
    public_input_explainer_method_html: "<p>위의 각 예시는 그것을 규율하는 시 페이지와, 그 종류의 현행 기록을 나열하는 이 사이트의 영역으로 연결됩니다. 이 설명은 그러한 절차가 일반적으로 어떻게 진행되는지를 다루며, 개별 건의 구체적인 날짜와 상태, 목적, 참여 경로는 해당 목록에 시정 기록부 출처 링크와 함께 남아 있습니다.</p>",
