    about_p_what_html: "CityScroll은 뉴욕시 공식 간행물을 연결하여 시 정부가 하는 일과 여러분이 다음에 할 수 있는 일을 이해하도록 돕습니다. 관련 기록을 모으면서 공개 출처 링크를 유지합니다. CityScroll은 독립적이며 시 정부 소속이 아닙니다. 날짜, 결정, 지침은 언제나 공식 공고를 기준으로 확인하세요.",
