    session_dismiss: "닫기",
    data_p_lede_html: "The City Record 데이터셋 한눈에 보기. 브라우저가 <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> (새 탭에서 열림)</span></a>에서 실시간 총계를 가져옵니다. 서버에는 아무것도 저장되지 않습니다. 이 수치들은 <a href=\"api.html#upstream\">솔직한 데이터 규칙</a>을 따릅니다. 통계는 해당 섹션 내에서만 집계됩니다. 입력 오류로 추정되는 항목(100억 달러 이상 금액)은 제외됩니다. 임시 마감일은 실제 날짜로 집계되지 않습니다.",
    data_h_sections_html: "기록이 실제로 보여주는 내용 <span class=\"note\">(전체 기간, 섹션별)</span>",
    data_note_sections_body: "The City Record의 대부분은 공무원 채용 관련 서류입니다. 시민에게 중요한 공고는 그중 일부에 불과합니다. 그래서 이 사이트의 모든 수치는 섹션별로 표시됩니다.",
    data_h_volume_html: "발행 건수 <span class=\"note\">(최근 12개월)</span>",
    data_h_procmix_html: "조달 구성 <span class=\"note\">(최근 12개월, 공고 유형별)</span>",
    data_h_agencies_html: "낙찰 금액 상위 기관 <span class=\"note\">(최근 12개월, 정제됨)</span>",
    data_note_agencies_html: "\"정제됨\"이란 100억 달러 이상의 금액을 제외했다는 뜻입니다. 저희는 이를 입력 오류로 판단합니다. <a href=\"api.html#upstream\">기초 데이터</a>를 참고하세요.",
    data_h_vendors_html: "낙찰 금액 상위 업체 <span class=\"note\">(최근 12개월, 정제됨)</span>",
