    stats_method_limits_desc: "몇 사람이 방문했는지, 검색이 질문에 답했는지는 알려줄 수 없습니다. 검색 횟수는 독자 수가 아닙니다.",
    stats_method_private_label: "비공개로 남는 것",
    stats_method_private_html: "위의 검색 횟수는 공개하지만 검색 내용 자체는 공개하지 않습니다. 방문, 관심 등록, 이메일 총계는 비공개로 유지됩니다. <a href=\"api.html#upstream\">출처 설명</a>을 읽거나 <a href=\"https://api.cityscroll.org/stats\">공개 JSON</a>을 여세요.",
